node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Search broader - any flights from JFK or to LHR
const fromJFK = db.prepare(\"SELECT flight_id, origin, destination, stops, route_type, status, dates_json FROM flights WHERE origin = 'JFK'\").all();
console.log('Flights from JFK:', JSON.stringify(fromJFK, null, 2));

const toLHR = db.prepare(\"SELECT flight_id, origin, destination, stops, route_type, status, dates_json FROM flights WHERE destination = 'LHR'\").all();
console.log('\\nFlights to LHR:', JSON.stringify(toLHR, null, 2));

// All unique origins and destinations
const origins = db.prepare('SELECT DISTINCT origin FROM flights').all();
const dests = db.prepare('SELECT DISTINCT destination FROM flights').all();
console.log('\\nAll origins:', origins.map(r=>r.origin));
console.log('All destinations:', dests.map(r=>r.destination));
console.log('\\nAll stops values:', db.prepare('SELECT DISTINCT stops FROM flights').all().map(r=>r.stops));
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Check if there are any connecting flight possibilities: JFK -> X -> LHR
const fromJFK = db.prepare(\"SELECT DISTINCT destination FROM flights WHERE origin = 'JFK'\").all();
const toLHR = db.prepare(\"SELECT DISTINCT origin FROM flights WHERE destination = 'LHR'\").all();
console.log('Destinations from JFK:', fromJFK.map(r=>r.destination));
console.log('Origins to LHR:', toLHR.map(r=>r.origin));

// Find common connecting airports
const jfkDests = new Set(fromJFK.map(r=>r.destination));
const lhrOrigins = new Set(toLHR.map(r=>r.origin));
const connecting = [...jfkDests].filter(x => lhrOrigins.has(x));
console.log('Possible connecting airports:', connecting);
"

